import { describe, expect, it } from 'vitest';

import { taxonomyRpcFailure } from './taxonomy-definition-response';
import type { TaxonomyOperation } from './taxonomy-rpc-table';

/**
 * BE03c 1298-1302: a message not generated by an operation's own catalog is a contract failure answered as a scrubbed
 * INTERNAL_ERROR 500. `canonical_source_unavailable` is generated only by CMS-03C-03 (BE03c 1375: defensively at
 * create, rename and alias; submission and activation belong to the governed review). Every other taxonomy operation
 * answers it exactly as it answers any other foreign reason (decision D-W4), never as a 502 dependency fault.
 */
const refusal = (): unknown => ({
  code: 'P0001',
  message: 'canonical_source_unavailable',
  details: JSON.stringify({ domain: 'role' }),
});

describe('canonical_source_unavailable outside CMS-03C-03', () => {
  it.each<TaxonomyOperation>([
    'CMS-03C-16',
    'CMS-03C-17',
    'cmsTaxonomyVersionsRead',
    'cmsTaxonomyTermsRead',
  ])('is a scrubbed 500 on %s', (operation) => {
    const error = taxonomyRpcFailure(400, refusal(), operation);
    expect(error.status).toBe(500);
    expect(JSON.stringify(error)).not.toMatch(/canonical_source|role/u);
  });

  it('is the typed 422 with its domain on CMS-03C-03', () => {
    const error = taxonomyRpcFailure(400, refusal(), 'CMS-03C-03');
    expect(error.status).toBe(422);
    expect(error.details).toMatchObject({
      reasonCode: 'canonical_source_unavailable',
      domain: 'role',
    });
  });

  it('keeps the default operation (CMS-03C-16) at 500 as well', () => {
    expect(taxonomyRpcFailure(400, refusal()).status).toBe(500);
  });
});
